def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell's value can be collected at most once, even if both paths pass through it.
    """
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = v

    # Edge case: single cell grid
    if N == 1:
        return grid[1][1]

    NEG_INF = -10**15
    # dp[i1][i2] holds max sum when first path is at (i1, j1) and second at (i2, j2)
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    # Total steps from start to end is 2*N - 2, but we use step index k = i + j
    for k in range(3, 2 * N + 1):
        new_dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # Consider all four combinations of previous moves
                for di1 in (0, 1):  # 0: came from left (i1), 1: came from up (i1-1)
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        pj1 = j1 - (1 - di1)
                        pj2 = j2 - (1 - di2)
                        if pi1 < 1 or pi2 < 1 or pj1 < 1 or pj2 < 1:
                            continue
                        val = dp[pi1][pi2]
                        if val > best:
                            best = val
                if best == NEG_INF:
                    continue
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                new_dp[i1][i2] = best + add
        dp = new_dp

    return dp[N][N] if dp[N][N] != NEG_INF else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if not coeffs:
        return "0"

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = "-" if coeff < 0 else ""
        else:
            sign = "-" if coeff < 0 else "+"

        abs_coeff = abs(coeff)

        # Determine coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ""
        else:
            coeff_part = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_part = f"x^{degree}"
        elif degree == 1:
            var_part = "x"
        else:
            var_part = ""

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first_term = False

    if not terms:
        return "0"

    return "".join(terms)

def decode(encoded, original, message):
    if len(encoded) != len(original):
        return "Failed"
    mapping = {}
    reverse_mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o
        if o in reverse_mapping:
            if reverse_mapping[o] != e:
                return "Failed"
        else:
            reverse_mapping[o] = e
    # Check mapping covers all 26 letters? We can check len(mapping) == 26
    if len(mapping) != 26:
        return "Failed"
    # Now decode message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])
    return ''.join(decoded_chars)

