def check_scenario(scenario, liar_count, statements, days_of_week):
    scenario = scenario.upper()
    liar_set = set(name.upper() for name in liar_count)
    days_set = set(day.upper() for day in days_of_week)
    for participant, stmts in statements.items():
        participant_upper = participant.upper()
        for stmt in stmts:
            s = stmt.upper()
            if any(day in s for day in days_set):
                continue
            truth = None
            if s.startswith('I AM GUILTY'):
                truth = (scenario == participant_upper)
            elif s.startswith('I AM NOT GUILTY'):
                truth = (scenario != participant_upper)
            elif ' IS GUILTY' in s:
                subject = s.split(' IS GUILTY')[0].strip()
                truth = (scenario == subject)
            elif ' IS NOT GUILTY' in s:
                subject = s.split(' IS NOT GUILTY')[0].strip()
                truth = (scenario != subject)
            else:
                continue
            if participant_upper in liar_set:
                if truth:
                    return False
            else:
                if not truth:
                    return False
    return True

def calculate_score(system: int, points: str) -> list:
    """
    ...
    """
    if not isinstance(system, int):
        raise TypeError("system must be an integer")
    if system not in (11, 21):
        raise ValueError("system must be 11 or 21")
    if not isinstance(points, str):
        raise TypeError("points must be a string")
    for ch in points:
        if ch not in ('W','L'):
            raise ValueError("points string must contain only 'W' and 'L'")
    player_score = 0
    opponent_score = 0
    result = []
    for ch in points:
        if ch == 'W':
            player_score += 1
        else:
            opponent_score += 1
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            result.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0
    if player_score > 0 or opponent_score > 0:
        result.append(f"{player_score}:{opponent_score}")
    return result

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 1:
        return 0

    # Compute LIS (strictly increasing) ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute LDS (strictly decreasing) starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum removals = total - longest bitonic subsequence
    return n - max_bitonic
